open(d+'/lib.py','w').write('''def components(grid, bg):
    """The 4-connected same-color components of non-background cells, as lists of (row, col)."""
    H, W = len(grid), len(grid[0])
    seen, comps = set(), []
    for i in range(H):
        for j in range(W):
            if grid[i][j] != bg and (i, j) not in seen:
                c = grid[i][j]; q = [(i, j)]; seen.add((i, j)); cells = []
                while q:
                    y, x = q.pop(); cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W and grid[ny][nx] == c and (ny, nx) not in seen:
                            seen.add((ny, nx)); q.append((ny, nx))
                comps.append(cells)
    return comps

def bbox(cells):
    """The (top, left, bottom, right) bounding box of a list of cells."""
    ys = [a for a, b in cells]; xs = [b for a, b in cells]
    return min(ys), min(xs), max(ys), max(xs)

def fill_rect_interiors(grid, fill_fn):
    """Fill the inside of each non-background component\'s bounding box with fill_fn(height, width)."""
    bg = grid[0][0]
    out = [r[:] for r in grid]
    for cells in components(grid, bg):
        a, b, y, x = bbox(cells)
        f = fill_fn(y - a + 1, x - b + 1)
        if f is not None:
            for r in range(a + 1, y):
                for c in range(b + 1, x):
                    out[r][c] = f
    return out

def parity_fill(h, w):
    """2 if the rectangle side is even, else 7 (task-8da2599a fill rule)."""
    return 2 if h % 2 == 0 else 7
